import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select } from '@linm-soft-org/linm-web-common-components';
import {
  listPaymentGuarantees,
  type PaymentGuaranteeFilterQuery,
  type PaymentGuaranteeListItem,
} from '../../../services/paymentGuarantees/endpoint';
import df from '../../../styles/documentForm.module.css';

type SearchState = {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  dienGiai: string;
  maPost: string;
  maGd: string;
  maQuyen: string;
  maPhi: string;
  maVv: string;
  maHd: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
};

const EMPTY_SEARCH: SearchState = {
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  dienGiai: '',
  maPost: '9',
  maGd: '',
  maQuyen: '',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
};

const MA_TD = ['maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5'] as const;
const EXTRA_CODES: { key: keyof SearchState; label: string }[] = [
  { key: 'maPhi', label: 'Khoản mục' },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'maKu', label: 'Khế ước' },
  { key: 'maTtln', label: 'Trung tâm lợi nhuận' },
  { key: 'maTtcp', label: 'Trung tâm chi phí' },
  { key: 'maBp', label: 'Phòng ban' },
  { key: 'maHs', label: 'Nhân sự' },
  { key: 'maCd', label: 'Công đoạn' },
];

const POST_VALUES = ['3', '5', '7', '9'] as const;

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function toQuery(state: SearchState): PaymentGuaranteeFilterQuery {
  const maPost = POST_VALUES.includes(state.maPost as (typeof POST_VALUES)[number]) ? state.maPost : '9';
  const query: PaymentGuaranteeFilterQuery = { maPost };
  const textKeys: (keyof SearchState)[] = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maKh', 'dienGiai',
    'maQuyen', 'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp', 'maBp', 'maHs', 'maCd',
    'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = state[key];
    if (typeof value === 'string' && value.trim()) {
      (query as Record<string, string>)[key] = value.trim();
    }
  });
  if (state.maGd === '2' || state.maGd === '3') query.maGd = state.maGd;
  if (state.locNsd) query.locNsd = true;
  return query;
}

const HblListPage: React.FC = () => {
  const navigate = useNavigate();
  const [search, setSearch] = useState<SearchState>(EMPTY_SEARCH);
  const [items, setItems] = useState<PaymentGuaranteeListItem[]>([]);
  const [filtering, setFiltering] = useState(false);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const patch = (next: Partial<SearchState>) => setSearch(prev => ({ ...prev, ...next }));

  const applyRows = (rows: PaymentGuaranteeListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadTop = async () => {
    setError('');
    setLoading(true);
    try {
      applyRows(await listPaymentGuarantees({ loadTop: 5 }));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách hạn mức, bảo lãnh thanh toán');
    } finally {
      setLoading(false);
    }
  };

  const runSearch = async (state: SearchState) => {
    setFiltering(true);
    setError('');
    setLoading(true);
    try {
      applyRows(await listPaymentGuarantees(toQuery(state)));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách hạn mức, bảo lãnh thanh toán');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadTop();
  }, []);

  const onSearch = () => {
    void runSearch(search);
  };

  const onRefresh = () => {
    if (!filtering) {
      void loadTop();
      return;
    }
    void runSearch(search);
  };

  const onEnter = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;
  const emptyText = filtering
    ? 'Không tìm thấy hạn mức, bảo lãnh thanh toán'
    : 'Không có hạn mức, bảo lãnh thanh toán';

  return (
    <div className={df.page} data-testid="ct-hbl-list">
      <h1 data-testid="ct-hbl-title">Hạn mức, bảo lãnh thanh toán</h1>
      <div>
        <Button variant="secondary" data-testid="ct-hbl-toolbar-refresh-btn" onClick={onRefresh} loading={loading}>
          Làm mới
        </Button>
        <Button variant="primary" data-testid="ct-hbl-toolbar-add-btn" onClick={() => navigate('/bh/hbl/them')}>
          Thêm
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hbl-toolbar-edit-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hbl/${encodeURIComponent(selectedSttRec)}`)}
        >
          Sửa
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hbl-toolbar-view-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hbl/${encodeURIComponent(selectedSttRec)}?mode=view`)}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hbl-toolbar-copy-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hbl/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}
        >
          Sao chép
        </Button>
      </div>

      <section className={df.section} data-testid="ct-hbl-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Ngày chứng từ từ</label>
            <Input type="date" data-testid="ct-hbl-search-ngayCt1" value={search.ngayCt1} onKeyDown={onEnter} onChange={e => patch({ ngayCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Ngày chứng từ đến</label>
            <Input type="date" data-testid="ct-hbl-search-ngayCt2" value={search.ngayCt2} onKeyDown={onEnter} onChange={e => patch({ ngayCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số chứng từ từ</label>
            <Input data-testid="ct-hbl-search-soCt1" value={search.soCt1} onKeyDown={onEnter} onChange={e => patch({ soCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số chứng từ đến</label>
            <Input data-testid="ct-hbl-search-soCt2" value={search.soCt2} onKeyDown={onEnter} onChange={e => patch({ soCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Đối tượng</label>
            <Input data-testid="ct-hbl-search-maKh" value={search.maKh} onKeyDown={onEnter} onChange={e => patch({ maKh: e.target.value })} />
          </div>
          <div className={`${df.field} ${df.spanCol2}`}>
            <label className={df.label}>Diễn giải</label>
            <Input data-testid="ct-hbl-search-dienGiai" value={search.dienGiai} onKeyDown={onEnter} onChange={e => patch({ dienGiai: e.target.value })} />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-hbl-search-btn" onClick={onSearch} loading={loading}>
          Tìm
        </Button>
      </section>

      <section className={df.section} data-testid="ct-hbl-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Trạng thái</label>
            <Select
              data-testid="ct-hbl-search-maPost"
              value={search.maPost}
              onChange={e => patch({ maPost: e.target.value })}
              options={[
                { value: '3', label: 'Hạn mức' },
                { value: '5', label: 'Bảo lãnh bằng tiền' },
                { value: '7', label: 'Thế chất tài sản' },
                { value: '9', label: 'Bảo lãnh ngân hàng' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại giao dịch</label>
            <Select
              data-testid="ct-hbl-search-maGd"
              value={search.maGd}
              onChange={e => patch({ maGd: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '2', label: 'Một đối tượng' },
                { value: '3', label: 'Nhiều đối tượng' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Quyền</label>
            <Input data-testid="ct-hbl-search-maQuyen" value={search.maQuyen} onKeyDown={onEnter} onChange={e => patch({ maQuyen: e.target.value })} />
          </div>
          {EXTRA_CODES.map(field => (
            <div className={df.field} key={field.key}>
              <label className={df.label}>{field.label}</label>
              <Input
                data-testid={`ct-hbl-search-${field.key}`}
                value={search[field.key] as string}
                onKeyDown={onEnter}
                onChange={e => patch({ [field.key]: e.target.value })}
              />
            </div>
          ))}
          {MA_TD.map((key, index) => (
            <div className={df.field} key={key}>
              <label className={df.label}>{`Mã tự do ${index + 1}`}</label>
              <Input
                data-testid={`ct-hbl-search-${key}`}
                value={search[key]}
                onKeyDown={onEnter}
                onChange={e => patch({ [key]: e.target.value })}
              />
            </div>
          ))}
          <div className={df.field}>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-hbl-search-locNsd"
              checked={search.locNsd}
              onChange={e => patch({ locNsd: e.target.checked })}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-hbl-grid">
          <thead>
            <tr>
              <th>Ngày</th>
              <th>Số CT</th>
              <th>Đối tượng</th>
              <th>Tên đối tượng</th>
              <th>Tổng tiền</th>
              <th>Diễn giải</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => {
              const selected = row.sttRec === selectedSttRec;
              return (
                <tr
                  key={row.sttRec}
                  aria-selected={selected}
                  onClick={() => setSelectedSttRec(row.sttRec)}
                  style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                >
                  <td>{showDate(row.ngayCt)}</td>
                  <td>{row.soCt}</td>
                  <td>{row.maKh}</td>
                  <td>{row.tenKh}</td>
                  <td>{showMoney(row.tPs ?? 0)}</td>
                  <td>{row.dienGiai}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {items.length === 0 ? <div>{emptyText}</div> : null}
    </div>
  );
};

export default HblListPage;
