export async function listPaymentGuarantees(
  query: PaymentGuaranteeFilterQuery,
): Promise<PaymentGuaranteeListItem[]> {
  const qs = new URLSearchParams();
  (Object.entries(query) as [string, string | number | boolean | undefined][]).forEach(([key, value]) => {
    if (value === undefined || value === '') return;
    if (key === 'locNsd' && value !== true) return;
    qs.set(key, String(value));
  });
  const suffix = qs.toString();
  const res = await apiClient.get<BffResponse<PaymentGuaranteeListItem[]>>(
    `/sales/payment-guarantees${suffix ? `?${suffix}` : ''}`,
  );
  return unwrap(res) ?? [];
}

export async function getPaymentGuarantee(sttRec: string): Promise<PaymentGuaranteeDetail> {
  const res = await apiClient.get<BffResponse<PaymentGuaranteeDetail>>(
    `/sales/payment-guarantees/${encodeURIComponent(sttRec)}`,
  );
  return unwrap(res);
}

export async function createPaymentGuarantee(
  body: PaymentGuaranteeWriteBody,
): Promise<PaymentGuaranteeDetail> {
  const res = await apiClient.post<BffResponse<PaymentGuaranteeDetail>>(
    '/sales/payment-guarantees',
    body,
  );
  return unwrap(res);
}

export async function updatePaymentGuarantee(
  sttRec: string,
  body: PaymentGuaranteeWriteBody,
): Promise<PaymentGuaranteeDetail> {
  const res = await apiClient.put<BffResponse<PaymentGuaranteeDetail>>(
    `/sales/payment-guarantees/${encodeURIComponent(sttRec)}`,
    body,
  );
  return unwrap(res);
}
